"""Host-only scheduling reference; not guest code or hardware qualification."""
class WindowReader:
 def __init__(self,size,exchange):
  self.size=size;self.exchange=exchange;self.open=False;self.commands=0;self.wire_bytes=0
 def command(self,block,keep_start=0,keep_end=0):
  expected=min(4096,self.size-block*4096)
  if not 0<=expected<=4096:raise ValueError('invalid block')
  output=bytearray();received=0
  def consume(value):
   nonlocal received
   if received>=expected:raise ValueError('excess response')
   if keep_start<=received<keep_end:output.append(value)
   received+=1
  self.commands+=1
  try:
   status=self.exchange(block,consume)
   self.wire_bytes+=received
   if status!=0 or received!=expected:raise ValueError('failed or short response')
  except BaseException:
   self.open=False
   raise
  self.open=(block*4096+received<self.size)
  return bytes(output)
 def __call__(self,offset,count):
  if not 0<count<=1024 or offset<0 or offset+count>self.size:raise ValueError('extent')
  output=bytearray()
  while count:
   block,inside=divmod(offset,4096);n=min(count,4096-inside)
   if block and not self.open:self.command(0)
   output.extend(self.command(block,inside,inside+n))
   offset+=n;count-=n
  return bytes(output)
 def close(self):
  if self.open:
   self.command((self.size-1)//4096)

def qualify():
 from pathlib import Path
 import sys,json,struct
 sys.path.insert(0,str(Path(__file__).resolve().parents[4]))
 from scripts.bluescsi_wav_contract import inspect_wav,RATES
 results=[]
 for channels in (1,2):
  for rate in RATES:
   for frames in (1,255,256,257,1023,1024,1025,4097):
    pcm=bytes((i*37+19)&255 for i in range(frames*channels*2))
    # Put fmt across a wire-block boundary to exercise a split header read.
    f=struct.pack('<HHIIHH',1,channels,rate,rate*channels*2,channels*2,16)
    body=b'WAVE'+b'JUNK'+struct.pack('<I',4066)+bytes(4066)+b'fmt '+struct.pack('<I',16)+f+b'data'+struct.pack('<I',len(pcm))+pcm
    data=b'RIFF'+struct.pack('<I',len(body))+body
    opened=False;last_reads=0
    def exchange(block,consume):
     nonlocal opened,last_reads
     if block==0:opened=True
     assert opened,'Nonzero request after EOF without reopening'
     start=block*4096;payload=data[start:start+4096]
     for value in payload:consume(value)
     if start+len(payload)>=len(data):opened=False;last_reads+=1
     return 0
    reader=WindowReader(len(data),exchange)
    info=inspect_wav(reader,len(data));assert (info.channels,info.rate,info.frames)==(channels,rate,frames)
    reconstructed=bytearray()
    for offset in range(0,len(pcm),1024):reconstructed.extend(reader(info.data_offset+offset,min(1024,len(pcm)-offset)))
    assert reconstructed==pcm
    # Arbitrary access after EOF must reopen before a nonzero block request.
    assert reader(info.data_offset,min(16,len(pcm)))==pcm[:min(16,len(pcm))]
    reader.close();assert not opened
    results.append(dict(channels=channels,rate=rate,frames=frames,pcm_bytes=len(pcm),commands=reader.commands,wire_bytes=reader.wire_bytes,eof_closes=last_reads))
 failures=[]
 for mode in ('status','short','excess'):
  def exchange(block,consume):
   for i in range({'status':16,'short':15,'excess':17}[mode]):consume(i)
   return 2 if mode=='status' else 0
  reader=WindowReader(16,exchange)
  try:reader(0,8)
  except ValueError:failures.append(mode)
  else:raise AssertionError(mode)
  assert not reader.open
 # One 360-byte page can represent any nine of the 100 original wire entries.
 listing=b''.join(bytes([i,1])+bytes([65+i%26])*33+(i*100).to_bytes(5,'big') for i in range(100))
 assert len(listing)==4000
 pages=[]
 for first in range(0,100,9):
  page=bytes(v for i,v in enumerate(listing) if first*40<=i<min(first+9,100)*40)
  assert len(page)<=360
  assert [page[i] for i in range(0,len(page),40)]==list(range(first,min(first+9,100)))
  pages.append(dict(first=first,bytes=len(page)))
 return dict(passed=True,wav_cases=results,error_cases=failures,directory_pages=pages,limitations=['Host scheduling model only; target semantics inferred from current upstream source, not pinned user firmware.','No target mutation/concurrency guarantee; selected index/name/size must be revalidated and directory state serialized.','Repeated wire reads trade bandwidth for local memory; no hardware speed claim.'])
if __name__=='__main__':
